"use client";

import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import {
    Award,
    Search as SearchIcon,
    Wallet,
    Plus as PlusIcon,
    Bell as BellIcon,
    LogOut
} from "lucide-react";

import ThemeToggle from "./ThemeToggle";

export default function Header({ onOpenJourney }: { onOpenJourney?: () => void }) {
    const { currentUser, logout } = useSimulation();

    let tier = 'Bronze';
    let tierColor = 'text-orange-700 bg-orange-500/10 border-orange-500/10';
    let tierIcon = <Award size={14} />;

    if (currentUser.sales_total >= 15000) {
        tier = 'Ouro';
        tierColor = 'text-amber-700 bg-amber-500/10 border-amber-500/10';
        tierIcon = <Award size={14} className="text-amber-500" />;
    } else if (currentUser.sales_total >= 5000) {
        tier = 'Prata';
        tierColor = 'text-slate-700 bg-slate-500/10 border-slate-500/10';
        tierIcon = <Award size={14} className="text-slate-400" />;
    }

    const renderAvatarContent = () => {
        if (currentUser.avatar) {
            return (
                <div
                    className="size-8 rounded-full bg-slate-200 bg-cover bg-center border border-white shadow-sm flex-shrink-0"
                    style={{ backgroundImage: `url('${currentUser.avatar}')` }}
                />
            );
        }
        const initials = currentUser.name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        return (
            <div className="size-8 bg-primary/20 rounded-full flex items-center justify-center text-primary font-bold text-[10px] border border-white shadow-sm flex-shrink-0">
                {initials}
            </div>
        );
    };

    return (
        <header className="sticky top-0 z-40 bg-transparent px-10 py-6">
            <div className="flex items-center justify-between max-w-full mx-auto w-full gap-10">
                <div className="flex items-center gap-4 flex-1">
                    <div className="relative w-full max-w-xl hidden md:block group">
                        <SearchIcon className="absolute left-6 top-1/2 -translate-y-1/2 text-on-surface-variant/20 transition-colors group-focus-within:text-primary" size={18} />
                        <input
                            className="w-full bg-[var(--accent)] border border-[var(--border)] rounded-xl py-3 pl-12 pr-6 focus:outline-none focus:bg-[var(--card)] focus:ring-4 focus:ring-primary/5 focus:border-primary text-xs font-medium transition-all placeholder:text-[var(--muted)]/50 shadow-sm"
                            placeholder="Pesquisar no painel..."
                            type="text"
                        />
                    </div>
                </div>

                <div className="flex items-center gap-6">
                    {/* Tier Badge - Dynamic */}
                    <div className={cn(
                        "flex items-center gap-3 px-6 py-2.5 rounded-full border transition-all duration-500 font-black text-[10px] uppercase tracking-[0.2em] shadow-sm",
                        tierColor
                    )}>
                        {tierIcon}
                        <span>{tier}</span>
                    </div>

                    {/* Sales Value Display */}
                    <div className="hidden sm:flex items-center gap-4 bg-[var(--card)] text-[var(--foreground)] px-6 py-2.5 rounded-full shadow-md transition-all border border-[var(--border)]">
                        <Wallet size={16} className="text-[var(--muted)]" />
                        <span className="text-xs font-black tracking-tight">
                            {currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </span>
                    </div>

                    <button
                        onClick={onOpenJourney}
                        className="bg-primary text-on-primary px-8 py-2.5 rounded-lg font-bold text-[10px] uppercase tracking-widest flex items-center gap-2 shadow-sm hover:bg-primary/90 transition-all active:scale-95"
                    >
                        <PlusIcon size={16} />
                        <span>+ Certificado</span>
                    </button>

                    <div className="flex items-center gap-4 ml-2">
                        <ThemeToggle className="p-2.5 rounded-full" />

                        <button className="flex items-center justify-center p-3 rounded-full text-[var(--muted)] hover:bg-[var(--accent)] transition-all relative">
                            <BellIcon size={20} />
                            <span className="absolute top-3 right-3 size-1.5 bg-primary rounded-full ring-2 ring-[var(--card)]"></span>
                        </button>

                        <div className="header-user-avatar cursor-pointer hover:scale-105 transition-all">
                            {renderAvatarContent()}
                        </div>
                    </div>
                </div>
            </div>

            {/* Mobile Search */}
            <div className="mt-4 md:hidden relative">
                <SearchIcon className="absolute left-5 top-1/2 -translate-y-1/2 text-on-surface-variant/40" size={16} />
                <input
                    className="w-full bg-surface-variant/20 border-none rounded-2xl py-3.5 pl-14 pr-6 focus:ring-2 focus:ring-primary/20 text-xs font-bold"
                    placeholder="Pesquisar..."
                    type="text"
                />
            </div>
        </header>
    );
}
